impl PlaceOrderService {
    pub async fn place(&self, cmd: PlaceOrderCommand) -> Result<OrderId, AppError> {
        let mut tx = self.pool.begin().await?;            // rollback on drop
        let customer = self.customers.of_id(&mut *tx, cmd.customer_id).await?;
        let order = customer.place_order(cmd.items)?;     // the aggregate decides
        self.orders.add(&mut *tx, &order).await?;
        tx.commit().await?;                               // one commit per use case
        Ok(order.id)
    }
}
